        if (subjectToAnnotationPick) {
          AnnotationPick pick = style.jakarta() ? AnnotationPick.JAKARTA : AnnotationPick.pick();
          @Nullable Boolean allowDecision = applyAnnotationPick(pick, annotationClass);

