    94	  /** Parses a pointer string. */
    95	  public static Pointer parse(String value) {
    96	    if (value == null) {
    97	      throw new MalformedPointerException("Pointer must not be null");
    98	    }
    99	    if (value.isEmpty()) {
   100	      return new Pointer(java.util.Collections.<String>emptyList());
   101	    }
   102	    if (value.charAt(0) != '/') {
   103	      throw new MalformedPointerException("Pointer must be empty or start with '/'");
   104	    }
   105	    java.util.ArrayList<String> steps = new java.util.ArrayList<String>();
   106	    int start = 1;
   107	    for (int index = 1; index <= value.length(); index++) {
   108	      if (index == value.length() || value.charAt(index) == '/') {
   109	        steps.add(unescape(value.substring(start, index)));
   110	        start = index + 1;
   111	      }
   112	    }
   113	    return new Pointer(steps);
   114	  }
